package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.math.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class TaskStatProvider extends AbstractLabDataSourceProvider { public TaskStatProvider(){super(ReportConfigCatalog.TASK_STAT,TaskDetailProvider.fields());} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){List<Map<String,Object>> r=copyRows(mapper().selectTaskStats(c)); Map<String,Object> x=new LinkedHashMap<String,Object>(); BigDecimal total=BigDecimal.ZERO; for(Map<String,Object> row:r) total=total.add(number(row.get("total"))); x.put("count",r.size()); x.put("total",total); return section(c,s,r,x);}}
